export const TOTAL_ROUNDS = 7;export const ROUND_WINDOW_MS = 6000;export const COAST_VISUAL_MS = 420;export const RESULT_DWELL_MS = 650;export const MAX_RUN_MS =TOTAL_ROUNDS * (ROUND_WINDOW_MS + COAST_VISUAL_MS + RESULT_DWELL_MS);export const PRESETS = [[82, 0.0052, 8, 0.00035, 170],[96, 0.0055, 8.2, 0.00042, 180],[110, 0.0057, 8.4, 0.0005, 200],[119, 0.006, 8.6, 0.00058, 220],[126, 0.0062, 8.8, 0.00066, 240],[134, 0.0065, 9, 0.00075, 260],[142, 0.0068, 9.2, 0.00086, 280],];const clamp = (value) =>Math.min(ROUND_WINDOW_MS, Math.max(0, Number(value) || 0));export function sampleFill(index, elapsedMs) {const preset = PRESETS[index];if (!preset) throw new RangeError("Unknown preset");const elapsed = clamp(elapsedMs);const units = elapsed * preset[1];return {elapsed,units,spend: units * (preset[2] + preset[3] * elapsed),};}export function scoreSample(spend, units, cap) {const ratio = cap ? spend / cap : 0;let category = "safe";let multiplier = 1;if (ratio > 1 + Number.EPSILON) [category, multiplier] = ["overshoot", 0];else if (ratio >= 0.98) [category, multiplier] = ["precision", 1.5];else if (ratio >= 0.95) [category, multiplier] = ["near", 1.2];return {category,multiplier,score: multiplier * units,accuracy: multiplier ? Math.min(100, ratio * 100) : 0,};}export function settleFill(index, holdMs, options = {}) {const hold = clamp(holdMs);const coastMs = options.coast === false || !hold ? 0 : PRESETS[index][4];const release = sampleFill(index, hold);const final = sampleFill(index, hold + coastMs);return {presetIndex: index,coastMs,release,final,...scoreSample(final.spend, final.units, PRESETS[index][0]),};}export const createRun = () => [];export function recordRound(run, result) {if (run.length >= TOTAL_ROUNDS) throw new RangeError("Exactly seven fills");if (result.presetIndex !== run.length) throw new RangeError("Wrong round");return [...run, result];}export function summarizeRun(run) {let totalUnits = 0;let totalScore = 0;let overshoots = 0;let bestAccuracy = 0;for (const result of run) {totalScore += result.score;if (result.category === "overshoot") overshoots += 1;else {totalUnits += result.final.units;bestAccuracy = Math.max(bestAccuracy, result.accuracy);}}return { totalUnits, totalScore, overshoots, bestAccuracy };}const BEST_KEY = "nownow-before-midnight-best-v1";export function readBest(storage) {try {const value = Number(storage?.getItem(BEST_KEY));return Number.isFinite(value) && value >= 0 ? value : 0;} catch {return 0;}}export function saveBest(storage, score) {const previous = readBest(storage);const best = Math.max(previous, Number.isFinite(score) ? score : 0);if (best > previous)try {storage?.setItem(BEST_KEY, String(best));} catch {return previous;}return best;}
